solutionCode:
pub struct Ponto {
    pub x: i32,
    pub y: i32,
}

pub fn ponto_de(x: i32, y: i32) -> Ponto {
    Ponto { x: x, y: y }
}

impl Ponto {
    pub fn dobrar_x(&mut self) -> i32 {
        self.x = self.x * 2;
        self.x
    }
}

