use desafio::ponto_de;

#[test]
fn testa_o_x_dobrado_do_ponto_dois_por_tres() {
    assert_eq!(ponto_de(2, 3).dobrar_x(), 4);
}

#[test]
fn testa_o_x_dobrado_do_ponto_tres_por_um() {
    assert_eq!(ponto_de(3, 1).dobrar_x(), 6);
}
